from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output,
)
from taf.rfrl.procedures.resources.python.parser.exceptions import (
    ConfigurationNotSupported
)


@log_input_and_output
def get_default_L2RtPoolDeployment_parameters(cell_technology):
    """
    Gets default list of required L2RtPoolDeployment parameters with default values.

    :param cell_technology: technology of tested cell for which default params will be returned,
                            possible two variants: "TDD" or "FDD"
    :type cell_technology: str

    :return: dict of default L2RtPoolDeployment parameters for particular cell technology, e.g. for "FDD:
                                {
                                 "connRrcPoolingAllowed": 'false',
                                 "scheUePoolingAllowed": 'false',
                                 "slowPrbPoolingAllowed": 'false',
                                 "slowPrbPoolingFddFr1EnhAllowed": 'false'
                                 }
    :rtype: dict

    :raises ConfigurationNotSupported: if provided cell technology is not supported.
    """
    if cell_technology == "TDD":
        return {
            "slowPrbPoolingTddFr1DlAllowed": 'false',
            "slowPrbPoolingTddFr1UlAllowed": 'false',
            "connRrcPoolingAllowed": 'false',
            "scheUePoolingAllowed": 'false',
            "subcellDeactivationDlAllowed": 'false',
            "dlSubcellDeactForARMAllowed": 'false',
            "spatialStreamPoolingAllowed": 'false'
        }
    elif cell_technology == "FDD":
        return {
            "connRrcPoolingAllowed": 'false',
            "scheUePoolingAllowed": 'false',
            "slowPrbPoolingAllowed": 'false',
            "slowPrbPoolingFddFr1EnhAllowed": 'false'
        }
    else:
        raise ConfigurationNotSupported("Cell technology '{}' is not supported".format(cell_technology))
